/** Print the RARE name of the given rule kind. */
std::ostream& operator<<(std::ostream& out, RareRuleKind kind);

/** A match of a RARE rewrite rule. */
struct RareMatch
{
  /** The maximum number of variables of a RARE rewrite rule. */
  static constexpr size_t MAX_VARS = 5;
  /** The kind of the matched rule. */
  RareRuleKind kind = RareRuleKind::NUM_RULES;
  /**
   * The nodes matched by the variables of the rule, in the order in which the
   * variables are declared.
   */
  std::array<Node, MAX_VARS> vars;
};

/**
 * Determine the RARE rewrite rules that may match the given node, i.e., the
 * rules whose match pattern has the same root kind as the node and children
 * of matching kinds.
 * @param node The node to match.
 * @return The candidate rules, in order of priority.
 */
const std::vector<RareRuleKind>& rare_candidates(const Node& node);

/**
 * Match the given RARE rewrite rule against the given node.
 *
 * The match patterns of RARE rules are matched against nodes in Bitwuzla's
 * normal form, i.e., ground subterms of a pattern only match values, and
 * the children of commutative operators are matched in any order.
 *
 * @param kind  The kind of the rule to match.
 * @param node  The node to match.
 * @param match Set to the match if the rule matches.
 * @return True if the rule matches the given node.
 */
bool rare_match(RareRuleKind kind, const Node& node, RareMatch& match);

/**
 * Construct the result of applying the matched RARE rewrite rule.
 * @param rewriter The rewriter used to construct (and rewrite) the result.
 * @param match    The match of the rule, determined via rare_match().
 * @return The rewritten node.
 */
Node rare_build(Rewriter& rewriter, const RareMatch& match);

